<script src="calendar.js" defer></script><script>document.querySelector('#song-request').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,out=document.querySelector('#request-result'),btn=f.querySelector('button');btn.disabled=true;out.textContent='Sending…';try{const r=await fetch(f.action,{method:'POST',body:new FormData(f),credentials:'same-origin'}),j=await r.json();out.textContent=j.success?'Request sent to the DJ!':(j.error||'Unable to send.');if(j.success)f.reset()}catch(err){out.textContent='Unable to send. Try again later.'}finally{btn.disabled=false}});</script></body></html>